// Psychology glossary — populated as lessons are built
const glossaryData = [
  // ═══ Chapter 1: Introduction to Psychology and Research Methods ═══
  { term: "Psychology", def: "The scientific study of behavior and mental processes." },
  { term: "Behavior", def: "Anything an organism does — overt (observable) or covert (internal, such as thinking)." },
  { term: "Empirical evidence", def: "Information gained from direct observation and measurement rather than opinion or tradition." },
  { term: "Critical thinking", def: "The ability to evaluate, compare, analyze, critique, and synthesize information; questioning assumptions and looking for alternate conclusions." },
  { term: "Scientific observation", def: "An empirical investigation structured so that it answers questions about the world." },
  { term: "Research method", def: "A systematic approach to answering scientific questions." },
  { term: "Description", def: "The first goal of psychology: naming and classifying behavior based on careful observation." },
  { term: "Understanding", def: "The second goal of psychology: stating the causes of a behavior." },
  { term: "Prediction", def: "The third goal of psychology: forecasting behavior accurately." },
  { term: "Control", def: "The fourth goal of psychology: altering conditions that influence behavior." },
  { term: "Introspection", def: "Looking inward to examine one's own thoughts, feelings, or sensations — the primary method of structuralism." },
  { term: "Structuralism", def: "The school of thought (Wundt, Titchener) that aimed to analyze experience into basic elements using introspection." },
  { term: "Functionalism", def: "The school of thought (James) concerned with how behavior and mental abilities help people adapt to their environments." },
  { term: "Natural selection", def: "Darwin's principle that physical features and behaviors that aid survival tend to be retained across generations." },
  { term: "Behaviorism", def: "The school of thought (Watson, Skinner) that emphasizes the study of overt, observable behavior and the effects of learning." },
  { term: "Stimulus", def: "Any physical energy sensed by an organism." },
  { term: "Response", def: "Any muscular action, glandular activity, or other identifiable aspect of behavior." },
  { term: "Radical behaviorism", def: "Skinner's view that behavior is shaped and maintained by its consequences, with no need to invoke mental events." },
  { term: "Cognitive behaviorism", def: "An approach combining behavioral principles with cognition (perception, thinking, anticipation) to explain behavior." },
  { term: "Gestalt psychology", def: "A school (Wertheimer) emphasizing the study of thinking, learning, and perception in whole units — 'the whole is greater than the sum of its parts.'" },
  { term: "Unconscious", def: "Contents of the mind that are beyond awareness — especially impulses and desires not directly known to a person (Freud)." },
  { term: "Repression", def: "The unconscious process by which threatening memories, thoughts, or impulses are held out of awareness." },
  { term: "Psychoanalysis", def: "Freud's approach to psychotherapy, emphasizing the exploration of unconscious conflicts." },
  { term: "Neo-Freudian", def: "A psychologist who accepts the broad features of Freud's theory but has revised it — often reducing emphasis on sex and aggression." },
  { term: "Psychodynamic theory", def: "Any theory of behavior emphasizing internal conflicts, motives, and unconscious forces." },
  { term: "Humanism", def: "An approach focusing on subjective human experience, problems, potentials, and ideals (Rogers, Maslow)." },
  { term: "Determinism", def: "The idea that all behavior has prior causes that would completely explain one's choices and actions if known." },
  { term: "Free will", def: "The idea that human beings are capable of freely making choices or decisions." },
  { term: "Self-actualization", def: "The ongoing process of fully developing one's personal potential (Maslow)." },
  { term: "Eclectic", def: "Drawing on multiple theoretical perspectives rather than a single school of thought." },
  { term: "Cognitive neuroscience", def: "The study of connections between mental events and activity in the brain." },
  { term: "Positive psychology", def: "The study of human strengths, virtues, and effective functioning (Seligman, Csikszentmihalyi)." },
  { term: "Cultural relativity", def: "The idea that behavior must be judged relative to the values of the culture in which it occurs." },
  { term: "Social norms", def: "Unspoken rules that define acceptable and expected behavior for members of a group." },

  // Research methods
  { term: "Scientific method", def: "Testing claims by careful measurement and controlled observation, using observation, hypothesis, evidence, publication, and theory building." },
  { term: "Hypothesis", def: "A tentative, testable prediction about the relationship between variables." },
  { term: "Operational definition", def: "Defining a concept by specifying the exact procedures used to measure it (e.g., defining 'hunger' as 'hours since last meal')." },
  { term: "Theory", def: "A system of ideas designed to interrelate concepts and facts, summarizing existing data and predicting future observations." },
  { term: "Naturalistic observation", def: "Observing behavior as it unfolds in natural settings, without interference." },
  { term: "Observer effect", def: "Changes in a subject's behavior caused by awareness of being observed." },
  { term: "Observer bias", def: "The tendency of an observer to distort observations to match expectations." },
  { term: "Anthropomorphic error", def: "Attributing human thoughts, feelings, or motives to animals — a special risk in animal research." },
  { term: "Correlational study", def: "A study that measures the degree of relationship between two or more existing variables, without manipulation." },
  { term: "Correlation coefficient", def: "A statistic (from −1.00 to +1.00) indicating the strength and direction of a relationship between two variables." },
  { term: "Positive correlation", def: "A relationship in which increases in one measure are matched by increases in the other." },
  { term: "Negative correlation", def: "A relationship in which increases in one measure are matched by decreases in the other." },
  { term: "Causation", def: "A cause-and-effect connection, which correlation alone cannot establish." },
  { term: "Experiment", def: "A formal trial in which the experimenter manipulates an independent variable to observe its effect on a dependent variable, while controlling other variables." },
  { term: "Independent variable (IV)", def: "The condition manipulated by the experimenter — the suspected cause." },
  { term: "Dependent variable (DV)", def: "The condition measured — the effect expected to depend on the independent variable." },
  { term: "Extraneous variables", def: "Conditions the researcher controls to prevent them from affecting the outcome." },
  { term: "Experimental group", def: "In a controlled experiment, the group exposed to the independent variable." },
  { term: "Control group", def: "In a controlled experiment, the group that receives no experimental manipulation, providing a baseline for comparison." },
  { term: "Random assignment", def: "Using chance (e.g., coin flip) to place subjects into experimental and control groups, balancing individual differences." },
  { term: "Statistical significance", def: "A result that would rarely occur by chance alone — conventionally, less than 5% of the time." },
  { term: "Meta-analysis", def: "A statistical technique combining the results of many studies on the same topic into a single analysis." },
  { term: "Placebo", def: "An inactive substance given in place of a drug to control for the effects of expectation." },
  { term: "Placebo effect", def: "Changes in behavior or physiology caused by the belief that one has received a treatment." },
  { term: "Single-blind experiment", def: "A design in which subjects do not know whether they are in the experimental or control group." },
  { term: "Double-blind experiment", def: "A design in which neither subjects nor experimenters know group assignments until the study is complete." },
  { term: "Experimenter effect", def: "Changes in behavior caused by the unintended influence of an experimenter's expectations." },
  { term: "Self-fulfilling prophecy", def: "A prediction that prompts people to act in ways that make the prediction come true." },
  { term: "Clinical method", def: "Studying psychological problems and therapies through intensive case studies of individuals." },
  { term: "Survey method", def: "Collecting information using questionnaires or interviews with large samples of people." },
  { term: "Representative sample", def: "A sample that accurately reflects the larger population being studied." },

  // Professions
  { term: "Psychologist", def: "A person highly trained in the methods, knowledge, and theories of psychology — typically holds a master's or doctoral degree." },
  { term: "Clinical psychologist", def: "A psychologist specializing in the treatment of psychological disorders or research on therapies." },
  { term: "Counseling psychologist", def: "A psychologist specializing in milder emotional and behavioral issues (e.g., school, work, relationships)." },
  { term: "Psychiatrist", def: "A medical doctor with additional training in diagnosing and treating mental disorders — can prescribe drugs." },
  { term: "Psychoanalyst", def: "A mental health professional (usually with an M.D. or Ph.D.) trained in Freudian psychoanalysis." },
  { term: "Counselor", def: "A mental health professional who helps with everyday problems (marriage, career, school) — typically holds a master's degree." },
  { term: "Basic research", def: "Research aimed at acquiring knowledge for its own sake." },
  { term: "Applied research", def: "Research aimed at solving immediate practical problems." },

  // ═══ Chapter 2: Brain and Behavior ═══
  { term: "Neuron", def: "An individual nerve cell — the basic building block of the nervous system." },
  { term: "Dendrites", def: "Branching fibers that receive incoming messages from other neurons." },
  { term: "Soma", def: "The cell body of a neuron; contains the nucleus and integrates incoming signals." },
  { term: "Axon", def: "The long fiber that carries nerve impulses away from the cell body toward other neurons, muscles, or glands." },
  { term: "Axon terminals", def: "The branching endings of an axon, which release neurotransmitters." },
  { term: "Myelin", def: "A fatty coating on many axons that speeds nerve impulse transmission." },
  { term: "Nerve", def: "A large bundle of neuron axons; unlike a neuron, nerves are visible to the naked eye." },
  { term: "Central nervous system (CNS)", def: "The brain and spinal cord." },
  { term: "Peripheral nervous system (PNS)", def: "All parts of the nervous system outside the brain and spinal cord." },
  { term: "Resting potential", def: "The electrical charge (~−70 mV) of a neuron at rest." },
  { term: "Threshold", def: "The level of voltage (~−50 mV) at which a neuron fires an action potential." },
  { term: "Action potential", def: "The all-or-nothing electrical nerve impulse that travels down an axon." },
  { term: "Ion channels", def: "Tiny gated openings in the axon membrane through which charged ions flow during an action potential." },
  { term: "All-or-nothing principle", def: "A neuron either fires at full strength or not at all — stimulus intensity is coded by firing rate, not spike size." },
  { term: "Synapse", def: "The microscopic gap between one neuron's axon terminal and another neuron's dendrite, across which chemical messages pass." },
  { term: "Neurotransmitter", def: "A chemical released by a neuron that alters activity in other neurons across the synapse." },
  { term: "Receptor sites", def: "Areas on the surface of neurons that are sensitive to specific neurotransmitters or hormones." },
  { term: "Acetylcholine", def: "The neurotransmitter that activates muscles; blocked by the poison curare." },
  { term: "Dopamine", def: "Neurotransmitter involved in reward, motivation, and motor control; low levels cause Parkinson's, excess is linked to schizophrenia." },
  { term: "Serotonin", def: "Neurotransmitter influencing mood, sleep, and appetite; targeted by many antidepressants." },
  { term: "GABA", def: "The brain's main inhibitory neurotransmitter; amplified by anti-anxiety drugs like Valium." },
  { term: "Glutamate", def: "The brain's main excitatory neurotransmitter; critical for learning and memory." },
  { term: "Neuropeptides", def: "Slower chemical regulators that modulate the activity of entire brain regions." },
  { term: "Endorphins", def: "The brain's natural opiate-like neuropeptides; released during stress, pain, and intense exercise (the 'runner's high')." },
  { term: "Somatic nervous system", def: "The division of the PNS that carries messages to and from sense organs and skeletal muscles — voluntary movement." },
  { term: "Autonomic nervous system (ANS)", def: "The division of the PNS serving internal organs and glands — largely automatic." },
  { term: "Sympathetic branch", def: "The part of the ANS that arouses the body for 'fight or flight.'" },
  { term: "Parasympathetic branch", def: "The part of the ANS that calms the body and supports 'rest and digest.'" },
  { term: "Reflex arc", def: "The simplest neural pathway — sensory neuron to connector neuron to motor neuron — producing an automatic response within the spinal cord." },
  { term: "Sensory neuron", def: "A nerve cell that carries information from sense organs toward the CNS." },
  { term: "Motor neuron", def: "A nerve cell that carries commands from the CNS to muscles and glands." },
  { term: "EEG (electroencephalograph)", def: "A device that detects and records the brain's electrical activity via scalp electrodes." },
  { term: "CT scan", def: "Computed tomography — a computer-enhanced X-ray producing structural images of the brain." },
  { term: "MRI scan", def: "Magnetic resonance imaging — uses magnets to produce detailed 3D images of brain anatomy." },
  { term: "fMRI scan", def: "Functional MRI — images brain activity in real time by detecting changes in blood flow." },
  { term: "PET scan", def: "Positron emission tomography — images brain activity by tracking radioactive glucose consumption." },
  { term: "Ablation", def: "The surgical removal of brain tissue to determine its function." },
  { term: "Deep lesioning", def: "Destruction of small areas of brain tissue using an implanted electrode." },
  { term: "Electrical stimulation of the brain (ESB)", def: "Activating brain tissue with small electrical currents to map function or treat disorders." },
  { term: "Cerebral cortex", def: "The wrinkled outer layer of the cerebrum; seat of higher mental functions." },
  { term: "Corticalization", def: "The increase in size and wrinkling of the cerebral cortex seen in advanced species." },
  { term: "Cerebral hemispheres", def: "The two halves of the cerebrum, connected by the corpus callosum." },
  { term: "Corpus callosum", def: "The thick band of fibers connecting the two cerebral hemispheres." },
  { term: "Occipital lobes", def: "Rear brain areas where vision registers." },
  { term: "Parietal lobes", def: "Upper brain areas where touch, temperature, pressure, and spatial information register." },
  { term: "Somatosensory cortex", def: "A strip in the parietal lobes mapping bodily sensation, with more area devoted to sensitive regions like lips and hands." },
  { term: "Temporal lobes", def: "Side brain areas containing auditory processing, language comprehension (Wernicke's area), and memory." },
  { term: "Frontal lobes", def: "Front brain areas responsible for movement, speech production, planning, reasoning, and personality." },
  { term: "Motor cortex", def: "An arch of tissue in the frontal lobes that directs voluntary muscle movement." },
  { term: "Broca's area", def: "Left-frontal language center; damage produces slow, labored speech (Broca's aphasia)." },
  { term: "Wernicke's area", def: "Left-temporal language center; damage produces fluent but meaningless speech (Wernicke's aphasia)." },
  { term: "Association cortex", def: "Cortical areas not directly sensory or motor; responsible for interpretation, integration, and higher thought." },
  { term: "Aphasia", def: "A language disorder resulting from brain damage, typically to Broca's or Wernicke's area." },
  { term: "Agnosia", def: "An inability to recognize or grasp the meaning of stimuli — 'mindblindness.'" },
  { term: "Facial agnosia (prosopagnosia)", def: "The inability to recognize familiar faces despite intact vision." },
  { term: "Split-brain operation", def: "Surgical cutting of the corpus callosum, used for severe epilepsy; results in each hemisphere operating independently." },
  { term: "Lateralization", def: "The specialization of the two hemispheres for different functions." },
  { term: "Subcortex", def: "All brain structures beneath the cerebral cortex." },
  { term: "Brainstem", def: "The lowest parts of the brain — includes medulla, pons, and reticular formation." },
  { term: "Medulla", def: "The lowest brainstem structure; controls heart rate, breathing, and other vital functions." },
  { term: "Pons", def: "A brainstem bridge that connects the medulla to higher structures and regulates sleep and arousal." },
  { term: "Cerebellum", def: "The 'little brain' at the back of the skull; controls posture, balance, fine motor coordination, and stores skill memories." },
  { term: "Reticular formation (RF)", def: "A network in the brainstem regulating attention, alertness, and reflexes." },
  { term: "Reticular activating system (RAS)", def: "The part of the reticular formation that activates the cortex to maintain wakefulness and alertness." },
  { term: "Thalamus", def: "The brain's sensory switchboard; routes nearly all sensory input to the cortex." },
  { term: "Hypothalamus", def: "A small but vital structure controlling hunger, thirst, temperature, sex, and the endocrine system." },
  { term: "Limbic system", def: "A group of subcortical structures (amygdala, hippocampus, etc.) involved in emotion and motivation." },
  { term: "Amygdala", def: "A limbic structure central to fear, emotional memory, and rapid threat detection." },
  { term: "Hippocampus", def: "A limbic structure critical for converting experiences into long-term memories." },
  { term: "Endocrine system", def: "The network of glands that secrete hormones into the bloodstream." },
  { term: "Hormone", def: "A chemical messenger secreted by an endocrine gland that travels through the bloodstream." },
  { term: "Pituitary gland", def: "The 'master gland' of the endocrine system; directed by the hypothalamus." },
  { term: "Adrenal glands", def: "Endocrine glands that release adrenaline (fight-or-flight) and cortisol (chronic stress)." },

  // ═══ Chapter 3: Child Development ═══
  { term: "Developmental psychology", def: "The study of progressive changes in behavior and abilities from conception to death." },
  { term: "Heredity (nature)", def: "The transmission of physical and psychological characteristics from parents to offspring through genes." },
  { term: "Environment (nurture)", def: "The sum of all external conditions that affect a developing person." },
  { term: "Chromosome", def: "Threadlike structures in every cell nucleus that carry genetic information — humans have 23 pairs." },
  { term: "Gene", def: "A specific region of a chromosome that carries the code for a particular trait or function." },
  { term: "Polygenic", def: "A trait influenced by many genes rather than just one (e.g., height, intelligence)." },
  { term: "Dominant gene", def: "A gene whose effect is expressed whenever present." },
  { term: "Recessive gene", def: "A gene whose effect is expressed only when inherited from both parents." },
  { term: "Sensitive period", def: "A span of development during which a child is especially receptive to certain environmental influences." },
  { term: "Teratogen", def: "Any environmental agent that can cause harm to a developing embryo or fetus (e.g., alcohol, rubella, lead)." },
  { term: "Fetal alcohol syndrome (FAS)", def: "A cluster of physical and cognitive abnormalities caused by prenatal alcohol exposure." },
  { term: "Neonate", def: "A newborn baby, typically from birth to one month old." },
  { term: "Grasping reflex", def: "The newborn's automatic grip on anything pressed into the palm." },
  { term: "Rooting reflex", def: "A newborn's automatic turning of the head toward anything that strokes the cheek." },
  { term: "Moro reflex", def: "A startle reflex in which the newborn flings arms outward and then inward." },
  { term: "Maturation", def: "The unfolding of genetically programmed physical changes that occur on a roughly universal schedule." },
  { term: "Temperament", def: "The hereditary, biological core of personality — including activity level, emotional reactivity, and soothability." },
  { term: "Goodness of fit", def: "The degree to which a child's temperament matches the demands of their environment." },
  { term: "Attachment", def: "The close emotional bond a baby forms with a primary caregiver." },
  { term: "Contact comfort", def: "The warmth and closeness of a caregiver's body, identified by Harlow as the primary basis of attachment." },
  { term: "Strange Situation", def: "Ainsworth's lab procedure for classifying infant attachment by observing reactions to brief separations and reunions." },
  { term: "Secure attachment", def: "An attachment pattern in which the infant uses the caregiver as a safe base and is easily comforted after separation." },
  { term: "Anxious/ambivalent attachment", def: "An insecure attachment pattern of strong distress at separation but resistance to comfort on reunion." },
  { term: "Avoidant attachment", def: "An insecure attachment pattern of apparent indifference to the caregiver's departure and return." },
  { term: "Disorganized attachment", def: "An insecure attachment pattern of contradictory reactions, often associated with caregiver maltreatment." },
  { term: "Cooing", def: "The earliest speech-like sounds (vowels) made by infants, typically around 2–6 months." },
  { term: "Babbling", def: "Repeated consonant-vowel sounds (e.g., 'ba-ba') beginning around 6 months; universal across cultures." },
  { term: "Telegraphic speech", def: "Early two-word utterances (e.g., 'want milk') that preserve the essential meaning while omitting grammatical words." },
  { term: "Parentese (motherese)", def: "The slower, higher-pitched, simplified speech style adults naturally use with babies, which aids language learning." },
  { term: "Language acquisition device", def: "Chomsky's proposed innate mental system that predisposes humans to acquire language." },
  { term: "Piaget's cognitive development theory", def: "Jean Piaget's theory that children pass through four qualitatively distinct stages of thinking." },
  { term: "Sensorimotor stage", def: "Piaget's first stage (0–2 yrs): intelligence based on direct sensory and motor exploration; object permanence emerges." },
  { term: "Object permanence", def: "The understanding that objects continue to exist when hidden from view, acquired during the sensorimotor stage." },
  { term: "Preoperational stage", def: "Piaget's second stage (2–7 yrs): use of language and symbols but still intuitive, egocentric, and lacking conservation." },
  { term: "Egocentrism", def: "A preoperational child's inability to take another person's perspective." },
  { term: "Conservation", def: "Understanding that quantity (mass, volume, number) stays the same despite changes in shape or appearance — mastered in concrete operations." },
  { term: "Concrete operational stage", def: "Piaget's third stage (7–11 yrs): logical reasoning about concrete, tangible situations; conservation mastered." },
  { term: "Reversibility", def: "Recognition that operations or relationships can be reversed (e.g., if 4+3=7, then 7-3=4)." },
  { term: "Formal operational stage", def: "Piaget's fourth stage (11+ yrs): abstract, hypothetical, and scientific reasoning." },
  { term: "Assimilation (Piaget)", def: "Fitting new experiences into existing mental schemes." },
  { term: "Accommodation (Piaget)", def: "Modifying existing mental schemes to fit new experiences." },
  { term: "Vygotsky's sociocultural theory", def: "Lev Vygotsky's view that cognitive development arises through social interaction with more skilled members of a culture." },
  { term: "Zone of proximal development (ZPD)", def: "The gap between what a child can do alone and what they can achieve with skilled guidance." },
  { term: "Scaffolding", def: "The temporary support a more knowledgeable person provides to help a child accomplish a task within the ZPD." },
  { term: "Erikson's psychosocial stages", def: "Erik Erikson's eight-stage lifespan theory in which each stage centers on a developmental crisis." },
  { term: "Trust vs. Mistrust", def: "Erikson's first stage (0–1 yr): reliable care builds basic trust in the world." },
  { term: "Autonomy vs. Shame/Doubt", def: "Erikson's second stage (1–3 yrs): toddlers develop independence by asserting self-control." },
  { term: "Initiative vs. Guilt", def: "Erikson's third stage (3–6 yrs): preschoolers develop the ability to plan and pursue goals through play and imagination." },
  { term: "Industry vs. Inferiority", def: "Erikson's fourth stage (6–12 yrs): school-age children develop competence in skills valued by their culture." },
  { term: "Authoritative parenting", def: "High demands + high warmth; clear rules with explanation and dialogue; associated with best child outcomes." },
  { term: "Authoritarian parenting", def: "High demands + low warmth; strict rules without negotiation; may produce obedient but anxious children." },
  { term: "Permissive parenting", def: "Low demands + high warmth; indulgent with few rules; children may struggle with self-regulation." },
  { term: "Uninvolved (neglectful) parenting", def: "Low demands + low warmth; linked to the poorest developmental outcomes." },

  // ═══ Chapter 4: Life-Span Development ═══
  { term: "Adolescence", def: "The social and psychological transition from childhood to adulthood." },
  { term: "Puberty", def: "The biological process of sexual maturation, marking the start of adolescence." },
  { term: "Identity vs. Role Confusion", def: "Erikson's adolescent crisis: building a coherent sense of who one is." },
  { term: "Identity diffusion", def: "Marcia's identity status of no exploration and no commitment." },
  { term: "Identity foreclosure", def: "Marcia's identity status of commitment without meaningful exploration." },
  { term: "Identity moratorium", def: "Marcia's identity status of active exploration without yet committing." },
  { term: "Identity achievement", def: "Marcia's identity status of commitment following genuine exploration." },
  { term: "Emerging adulthood", def: "Arnett's proposed stage (roughly 18–25) in industrialized societies marked by exploration, instability, and self-focus." },
  { term: "Intimacy vs. Isolation", def: "Erikson's early-adulthood crisis: forming deep, committed relationships." },
  { term: "Generativity vs. Stagnation", def: "Erikson's middle-adulthood crisis: contributing to the next generation and society." },
  { term: "Integrity vs. Despair", def: "Erikson's late-life crisis: accepting one's life as meaningful versus feeling regret." },
  { term: "Fluid intelligence", def: "Fast, abstract problem-solving ability; peaks in the 20s and slowly declines with age." },
  { term: "Crystallized intelligence", def: "Accumulated knowledge and verbal skills; often grows into old age." },
  { term: "Cognitive reserve", def: "The brain's resistance to damage and decline, built by education, stimulation, and lifestyle." },
  { term: "Positivity effect", def: "The tendency of older adults to remember and attend to positive information more than negative." },
  { term: "Socioemotional selectivity theory", def: "Carstensen's theory that as time horizons shorten, people prioritize emotionally meaningful relationships." },
  { term: "Ageism", def: "Prejudice or stereotyping based on age; often self-fulfilling in elderly individuals." },
  { term: "Kübler-Ross stages", def: "Five common reactions to dying or loss: denial, anger, bargaining, depression, acceptance — not a strict sequence." },

  // ═══ Chapter 5: Sensation and Reality ═══
  { term: "Sensation", def: "The process by which sensory receptors detect physical stimuli and convert them into neural signals." },
  { term: "Perception", def: "The organization and interpretation of sensory information into meaningful experience." },
  { term: "Transduction", def: "The conversion of physical energy (light, sound, pressure) into neural signals." },
  { term: "Psychophysics", def: "The study of the relationship between physical stimuli and psychological experience." },
  { term: "Absolute threshold", def: "The weakest stimulus a person can detect 50% of the time." },
  { term: "Difference threshold (JND)", def: "The just-noticeable difference — smallest change between two stimuli a person can detect." },
  { term: "Weber's law", def: "The principle that the JND is a constant proportion of the original stimulus." },
  { term: "Signal detection theory", def: "A framework that separates sensory sensitivity from response bias in detecting weak signals." },
  { term: "Sensory adaptation", def: "The diminished sensitivity to a constant, unchanging stimulus." },
  { term: "Retina", def: "The light-sensitive layer at the back of the eye, containing rods and cones." },
  { term: "Rods", def: "Retinal photoreceptors specialized for low-light and peripheral vision; no color." },
  { term: "Cones", def: "Retinal photoreceptors concentrated in the fovea; responsible for color and fine detail." },
  { term: "Fovea", def: "The central retinal area with the highest density of cones and sharpest vision." },
  { term: "Blind spot", def: "The point where the optic nerve exits the retina — contains no photoreceptors." },
  { term: "Trichromatic theory", def: "Young-Helmholtz theory that color vision is based on three cone types (red, green, blue)." },
  { term: "Opponent-process theory", def: "Theory that color vision is based on neural pairs (red-green, blue-yellow, black-white) acting in opposition." },
  { term: "Cochlea", def: "The spiral, fluid-filled structure in the inner ear containing hair cells that transduce sound." },
  { term: "Pitch", def: "The psychological experience of sound frequency — higher frequency = higher pitch." },
  { term: "Conduction deafness", def: "Hearing loss caused by damage to the outer or middle ear; often treatable." },
  { term: "Sensorineural (nerve) deafness", def: "Hearing loss from damage to cochlear hair cells or the auditory nerve." },
  { term: "Olfaction", def: "The sense of smell; detects airborne chemicals via receptors in the nose." },
  { term: "Gustation", def: "The sense of taste; detects sweet, sour, salty, bitter, and umami." },
  { term: "Kinesthesis", def: "The sense of body-part position and movement." },
  { term: "Vestibular sense", def: "The sense of balance and spatial orientation, from fluid in the inner ear." },
  { term: "Gate control theory", def: "Melzack & Wall's theory that a neural 'gate' in the spinal cord modulates pain signals." },

  // ═══ Chapter 6: Perceiving the World ═══
  { term: "Gestalt principles", def: "Rules by which the brain groups sensory elements into meaningful wholes — proximity, similarity, closure, continuity, figure-ground." },
  { term: "Figure-ground", def: "The Gestalt principle of separating a perceived object (figure) from its background (ground)." },
  { term: "Proximity", def: "The Gestalt principle that items close together are perceived as grouped." },
  { term: "Similarity", def: "The Gestalt principle that similar-looking items are perceived as grouped." },
  { term: "Closure", def: "The Gestalt principle of mentally filling in gaps to perceive complete objects." },
  { term: "Continuity", def: "The Gestalt principle of preferring smooth, continuous patterns over abrupt discontinuities." },
  { term: "Depth perception", def: "The ability to see the world in three dimensions and judge distances." },
  { term: "Binocular cues", def: "Depth cues requiring both eyes — retinal disparity and convergence." },
  { term: "Retinal disparity", def: "The slight difference between the images on each retina, used to judge depth." },
  { term: "Convergence", def: "The inward turning of the eyes as an object gets closer; a binocular depth cue." },
  { term: "Monocular cues", def: "Depth cues that require only one eye, such as linear perspective and relative size." },
  { term: "Perceptual constancy", def: "Perceiving objects as stable (in size, shape, color, brightness) despite changing sensory input." },
  { term: "Top-down processing", def: "Perception driven by higher-level knowledge, expectations, and context." },
  { term: "Bottom-up processing", def: "Perception built directly from raw sensory input, without prior expectations." },
  { term: "Perceptual set", def: "A readiness to perceive in a particular way, shaped by expectations, context, or motivation." },
  { term: "Müller-Lyer illusion", def: "A classic visual illusion in which two equal lines appear different in length due to arrowhead directions." },
  { term: "Extrasensory perception (ESP)", def: "Claimed perception beyond the known senses (telepathy, clairvoyance, precognition); no reliable evidence supports it." },

  // ═══ Chapter 7: States of Consciousness ═══
  { term: "Consciousness", def: "Awareness of oneself and the environment." },
  { term: "Circadian rhythm", def: "A roughly 24-hour biological cycle regulating sleep, alertness, and physiology." },
  { term: "Suprachiasmatic nucleus (SCN)", def: "The hypothalamic structure that acts as the brain's master clock, synchronized by light." },
  { term: "Melatonin", def: "A hormone released by the pineal gland that cues the body for sleep." },
  { term: "Non-REM sleep", def: "The non-REM sleep stages (1–3), including slow-wave deep sleep." },
  { term: "REM sleep", def: "Rapid-eye-movement sleep marked by high brain activity, vivid dreams, and body paralysis." },
  { term: "Slow-wave sleep", def: "Deep non-REM sleep (stage 3), characterized by large, slow delta brain waves." },
  { term: "Insomnia", def: "Persistent difficulty falling or staying asleep." },
  { term: "Sleep apnea", def: "A disorder of repeated brief breathing pauses during sleep, linked to cardiovascular problems." },
  { term: "Narcolepsy", def: "A rare disorder marked by sudden, uncontrollable sleep attacks during the day." },
  { term: "Activation-synthesis hypothesis", def: "Hobson & McCarley's theory that dreams arise from the cortex's attempt to make sense of random REM-sleep signals." },
  { term: "Manifest content", def: "Freud's term for what a dreamer actually remembers of a dream — its surface story." },
  { term: "Latent content", def: "Freud's term for the supposed hidden symbolic meaning beneath the manifest dream." },
  { term: "Hypnosis", def: "A state of focused attention, reduced peripheral awareness, and heightened suggestibility." },
  { term: "Meditation", def: "Practices that train attention and awareness, commonly concentrative (one focus) or mindfulness (open monitoring)." },
  { term: "Psychoactive drug", def: "Any substance that alters perception, mood, cognition, or behavior by affecting brain chemistry." },
  { term: "Depressant", def: "A drug that slows nervous system activity (alcohol, benzodiazepines)." },
  { term: "Stimulant", def: "A drug that speeds nervous system activity (caffeine, nicotine, cocaine, amphetamines)." },
  { term: "Opioid", def: "A class of powerful pain-relieving, euphoric, and highly addictive drugs (morphine, heroin, fentanyl)." },
  { term: "Hallucinogen", def: "A drug that profoundly alters perception and cognition (LSD, psilocybin, mescaline)." },
  { term: "Tolerance", def: "A reduced response to a drug with repeated use, requiring more for the same effect." },
  { term: "Physical dependence", def: "A state in which stopping a drug produces physiological withdrawal symptoms." },
  { term: "Addiction", def: "Compulsive drug-seeking and use despite harmful consequences; now understood as a chronic brain condition." },

  // ═══ Chapter 8: Conditioning and Learning ═══
  { term: "Learning", def: "A relatively permanent change in behavior or knowledge resulting from experience." },
  { term: "Classical conditioning", def: "Learning in which a neutral stimulus becomes able to evoke a response by being paired with an unconditioned stimulus (Pavlov)." },
  { term: "Unconditioned stimulus (US)", def: "A stimulus that naturally and automatically triggers a response." },
  { term: "Unconditioned response (UR)", def: "The automatic, unlearned response to an unconditioned stimulus." },
  { term: "Neutral stimulus (NS)", def: "A stimulus that, before conditioning, does not trigger the target response." },
  { term: "Conditioned stimulus (CS)", def: "A previously neutral stimulus that, after pairing, triggers a conditioned response." },
  { term: "Conditioned response (CR)", def: "The learned response to a conditioned stimulus." },
  { term: "Acquisition", def: "The initial learning phase in which a CS-US association is established." },
  { term: "Extinction", def: "The weakening and eventual disappearance of a conditioned response when the CS is no longer paired with the US." },
  { term: "Spontaneous recovery", def: "Reappearance of a previously extinguished response after a rest period." },
  { term: "Stimulus generalization", def: "Responding to stimuli similar to the CS as if they were the CS itself." },
  { term: "Stimulus discrimination", def: "Learning to respond to a specific CS but not to similar stimuli." },
  { term: "Little Albert", def: "Infant subject in Watson and Rayner's 1920 study demonstrating that fear could be classically conditioned in humans." },
  { term: "Systematic desensitization", def: "Exposure-based therapy that replaces a fear response with relaxation through graded exposure (Wolpe)." },
  { term: "Taste aversion", def: "Rapid, strong classical conditioning of a dislike for a food paired (even once) with nausea." },
  { term: "Operant conditioning", def: "Learning in which voluntary behavior is strengthened or weakened by its consequences (Skinner)." },
  { term: "Law of Effect", def: "Thorndike's principle that behaviors followed by satisfying consequences are more likely to recur." },
  { term: "Skinner box (operant chamber)", def: "A controlled environment used to study operant conditioning in animals." },
  { term: "Positive reinforcement", def: "Adding a desirable consequence after a behavior, making the behavior more likely." },
  { term: "Negative reinforcement", def: "Removing an aversive consequence after a behavior, making the behavior more likely." },
  { term: "Positive punishment", def: "Adding an aversive consequence after a behavior, making the behavior less likely." },
  { term: "Negative punishment", def: "Removing a desirable consequence after a behavior, making the behavior less likely." },
  { term: "Primary reinforcer", def: "An intrinsically rewarding stimulus (food, water, warmth)." },
  { term: "Secondary reinforcer", def: "A learned reinforcer that gains reward value through association with primary reinforcers (money, praise, grades)." },
  { term: "Shaping", def: "Reinforcing successive approximations of a target behavior to build complex behavior gradually." },
  { term: "Schedules of reinforcement", def: "Rules determining when reinforcement is delivered — fixed or variable, ratio or interval." },
  { term: "Fixed ratio (FR)", def: "Reinforcement after a set number of responses." },
  { term: "Variable ratio (VR)", def: "Reinforcement after an unpredictable number of responses; produces the highest, most persistent response rates." },
  { term: "Fixed interval (FI)", def: "Reinforcement for the first response after a set time period." },
  { term: "Variable interval (VI)", def: "Reinforcement for the first response after an unpredictable time period; produces steady moderate rates." },
  { term: "Latent learning", def: "Learning that occurs without immediate reinforcement and is not demonstrated until incentive appears (Tolman)." },
  { term: "Cognitive map", def: "A mental representation of the layout of an environment (Tolman)." },
  { term: "Insight learning", def: "Sudden comprehension of a problem's solution, without gradual trial-and-error (Köhler)." },
  { term: "Observational learning", def: "Learning by watching others (Bandura); also called social learning." },
  { term: "Bobo doll experiment", def: "Bandura's classic 1961 study showing children imitated aggressive adult models." },
  { term: "Mirror neurons", def: "Brain cells that fire both when performing an action and when watching another perform it; possibly involved in imitation and empathy." },
  { term: "Instinctive drift", def: "The tendency for trained behavior to drift back toward instinctive patterns (Breland & Breland)." },

  // ═══ Chapter 9: Memory ═══
  { term: "Memory", def: "The mental system that encodes, stores, and retrieves information across time." },
  { term: "Encoding", def: "The process of converting information into a form that can be stored in memory." },
  { term: "Storage", def: "The retention of encoded information over time." },
  { term: "Retrieval", def: "The process of accessing stored information." },
  { term: "Atkinson-Shiffrin model", def: "A classic three-stage model of memory: sensory → short-term → long-term." },
  { term: "Sensory memory", def: "Very brief (fraction of a second to a few seconds) storage of sensory input before attention selects from it." },
  { term: "Iconic memory", def: "Brief visual sensory memory — roughly half a second." },
  { term: "Echoic memory", def: "Brief auditory sensory memory — 3–4 seconds." },
  { term: "Short-term memory (STM)", def: "A limited-capacity store holding information for ~20–30 seconds without rehearsal; roughly 4–7 chunks." },
  { term: "Chunk", def: "A meaningful unit of information — can be a digit, word, or entire phrase depending on expertise." },
  { term: "Working memory", def: "Baddeley's expanded model of STM with phonological loop, visuospatial sketchpad, central executive, and episodic buffer." },
  { term: "Phonological loop", def: "The component of working memory that holds and rehearses verbal information." },
  { term: "Visuospatial sketchpad", def: "The component of working memory that holds visual and spatial information." },
  { term: "Central executive", def: "The attention-directing, coordinating component of working memory." },
  { term: "Long-term memory (LTM)", def: "Memory storage of essentially unlimited capacity and duration." },
  { term: "Explicit (declarative) memory", def: "Memory for facts and experiences that can be consciously reported." },
  { term: "Episodic memory", def: "Explicit memory of personal experiences, tied to specific times and places." },
  { term: "Semantic memory", def: "Explicit memory of general knowledge and facts." },
  { term: "Implicit (non-declarative) memory", def: "Memory affecting behavior without conscious awareness — e.g., skills, habits, classical conditioning, priming." },
  { term: "Procedural memory", def: "Implicit memory for motor skills and habits." },
  { term: "Priming", def: "Facilitation of later processing because of earlier exposure to related information." },
  { term: "Levels of processing", def: "Craik & Lockhart's theory that deeper (semantic) processing produces better memory than shallow (structural or phonemic) processing." },
  { term: "Elaboration", def: "Connecting new material to existing knowledge to strengthen memory." },
  { term: "Self-reference effect", def: "The enhanced memory for information that is related to oneself." },
  { term: "Hippocampus (in memory)", def: "Brain structure critical for forming and consolidating new explicit memories." },
  { term: "Long-term potentiation (LTP)", def: "Long-lasting strengthening of synaptic connections with repeated stimulation; cellular basis of learning." },
  { term: "H.M. (Henry Molaison)", def: "Patient whose 1953 hippocampal surgery revealed that explicit and implicit memory are separate systems." },
  { term: "Context-dependent memory", def: "Better recall when retrieval context matches encoding context." },
  { term: "State-dependent memory", def: "Better recall when the internal state at retrieval matches the state at encoding." },
  { term: "Mood-congruent memory", def: "Tendency to recall memories matching your current mood." },
  { term: "Testing effect", def: "Active retrieval (practice testing) produces much better long-term retention than re-reading." },
  { term: "Forgetting curve", def: "Ebbinghaus's demonstration that memory loss is rapid at first, then levels off." },
  { term: "Proactive interference", def: "Old memories interfering with the retrieval of newer ones." },
  { term: "Retroactive interference", def: "New memories interfering with the retrieval of older ones." },
  { term: "Spaced practice (distributed practice)", def: "Spreading study across multiple sessions; produces much better long-term retention than massed cramming." },
  { term: "Misinformation effect", def: "Incorporating post-event information into memory, producing distorted recall of the original event (Loftus)." },
  { term: "False memory", def: "A genuinely believed recollection of an event that did not actually happen as remembered." },
  { term: "Flashbulb memory", def: "A vivid, emotionally charged memory of a surprising or important event — feels accurate but is no more accurate than ordinary memory." },
  { term: "Retrograde amnesia", def: "Loss of memories formed before the onset of amnesia." },
  { term: "Anterograde amnesia", def: "Inability to form new memories after the onset of amnesia." },
  { term: "Mnemonic", def: "A memory-aiding technique such as the method of loci, acronyms, or rhymes." },
  { term: "Method of loci", def: "An ancient mnemonic of mentally placing items along a familiar spatial route." },

  // ═══ Chapter 10: Cognition, Language, and Creativity ═══
  { term: "Cognition", def: "The mental activities involved in acquiring, processing, and using information — thinking, knowing, remembering, judging, problem-solving." },
  { term: "Concept", def: "A mental category that groups similar objects, events, or ideas, allowing efficient generalization." },
  { term: "Prototype theory", def: "Rosch's theory that concepts are represented by the most typical example; atypical members are categorized more slowly." },
  { term: "Exemplar theory", def: "Theory that concepts are represented by specific remembered examples, with new items judged by similarity to them." },
  { term: "Algorithm", def: "A step-by-step procedure guaranteed to solve a problem if a solution exists." },
  { term: "Heuristic", def: "A rule-of-thumb shortcut in problem-solving or judgment; usually fast, not guaranteed to be correct." },
  { term: "Means-end analysis", def: "A problem-solving strategy of reducing the difference between the current state and the goal state step by step." },
  { term: "Insight", def: "A sudden, often unexpected reorganization of a problem that yields its solution." },
  { term: "Mental set", def: "The tendency to approach problems using strategies that have worked in the past, even when better approaches exist." },
  { term: "Functional fixedness", def: "The tendency to perceive objects only in their usual function, blocking novel uses." },
  { term: "Availability heuristic", def: "Judging probability by how easily examples come to mind; produces biases toward vivid, recent events." },
  { term: "Representativeness heuristic", def: "Judging probability by how well something fits a stereotype; can violate basic probability rules." },
  { term: "Anchoring", def: "The bias by which an initial number biases subsequent numerical judgments, even when the anchor is irrelevant." },
  { term: "Confirmation bias", def: "The tendency to seek, remember, and favor information that supports one's existing beliefs." },
  { term: "Framing effect", def: "The way information is presented — as a gain vs. a loss, for instance — alters decisions even when the underlying facts are identical." },
  { term: "Sunk-cost fallacy", def: "Continuing a losing course because of prior investment, rather than evaluating the future on its own merits." },
  { term: "System 1 / System 2 (Kahneman)", def: "Two modes of thinking: System 1 is fast, automatic, and intuitive; System 2 is slow, effortful, and deliberate." },
  { term: "Language", def: "A rule-governed system of symbols used to communicate meaning." },
  { term: "Phoneme", def: "The smallest distinguishable unit of sound in a language." },
  { term: "Morpheme", def: "The smallest meaning-bearing unit of language (e.g., 'un-', 'happy', '-ness')." },
  { term: "Syntax", def: "The rules governing how words combine into phrases and sentences." },
  { term: "Semantics", def: "The meaning of words and sentences." },
  { term: "Linguistic relativity", def: "The hypothesis (Whorf) that language shapes thought; strong form rejected, weaker form supported." },
  { term: "Creativity", def: "The ability to produce ideas or products that are both novel and useful." },
  { term: "Convergent thinking", def: "Narrowing options to find a single correct answer." },
  { term: "Divergent thinking", def: "Generating many possible answers to a single question; associated with creativity." },
  { term: "Wallas's four stages", def: "Preparation, incubation, illumination, verification — a classic model of creative thinking." },
  { term: "Incubation", def: "The unconscious processing that continues while a problem is set aside, often preceding an insight." },
  { term: "Intuition", def: "Rapid, effortless judgments that emerge without conscious deliberation; reliable for experts in feedback-rich domains, less so elsewhere." },

  // ═══ Chapter 11: Intelligence ═══
  { term: "Intelligence", def: "The ability to learn from experience, adapt to new situations, understand abstract concepts, and use knowledge to solve problems." },
  { term: "General intelligence (g)", def: "Spearman's concept of a single underlying cognitive factor that explains why performance across different cognitive tests is correlated." },
  { term: "Multiple intelligences (Gardner)", def: "Theory that intelligence has eight or more relatively independent domains including linguistic, logical-mathematical, musical, and interpersonal." },
  { term: "Triarchic theory (Sternberg)", def: "Theory that intelligence has three interacting aspects: analytical, creative, and practical." },
  { term: "Emotional intelligence (EQ)", def: "The ability to perceive, understand, manage, and use emotions in oneself and others." },
  { term: "Mental age", def: "A measure of intellectual performance relative to typical age norms; a 10-year-old performing at the 12-year-old level has mental age 12 (Binet)." },
  { term: "Intelligence quotient (IQ)", def: "Originally mental age / chronological age × 100; now a deviation score with mean 100 and standard deviation 15." },
  { term: "Stanford-Binet", def: "The American adaptation (Terman, 1916) of Binet's intelligence test; remains a major individually-administered IQ test." },
  { term: "WAIS / WISC", def: "Wechsler Adult Intelligence Scale / Wechsler Intelligence Scale for Children — the most widely used individually-administered IQ tests." },
  { term: "Reliability", def: "The consistency of a measurement across repeated administrations." },
  { term: "Validity", def: "The degree to which a test measures what it claims to measure." },
  { term: "Standardization", def: "Administering a test under consistent conditions to a large representative sample, establishing norms for comparison." },
  { term: "Normal distribution (bell curve)", def: "A symmetric bell-shaped distribution; IQ is standardized so that mean = 100 and standard deviation = 15." },
  { term: "Intellectual disability", def: "Significantly below-average cognitive functioning (IQ ~70) combined with adaptive-skill limitations." },
  { term: "Giftedness", def: "Cognitive functioning significantly above average, typically IQ ~130 or higher." },
  { term: "Heritability", def: "The proportion of variance in a trait within a population attributable to genetic differences. Does not imply between-group differences are genetic." },
  { term: "Flynn effect", def: "The finding that measured IQ scores rose by roughly 3 points per decade across the 20th century, likely from environmental improvements." },
  { term: "Stereotype threat", def: "The performance drop that occurs when a person is reminded of a negative stereotype about their group on the task at hand." },
  { term: "Grit", def: "Passion and perseverance for long-term goals (Duckworth); a predictor of achievement partly independent of IQ." },
  { term: "Growth mindset", def: "The belief that abilities can be developed through effort (Dweck); contrasted with fixed mindset." },

  // ═══ Chapter 12: Motivation and Emotion ═══
  { term: "Motivation", def: "Processes that initiate, direct, and sustain behavior." },
  { term: "Drive (Hull)", def: "An aversive internal state arising from unmet biological need, which motivates behavior to reduce it." },
  { term: "Homeostasis", def: "The body's tendency to maintain internal physiological balance." },
  { term: "Incentive theory", def: "Theory that behavior is pulled by external rewards rather than pushed by internal drives." },
  { term: "Arousal theory", def: "Theory that organisms seek an optimal level of physiological and psychological arousal." },
  { term: "Yerkes-Dodson law", def: "The principle that performance is best at moderate arousal — and at lower arousal for more complex tasks." },
  { term: "Maslow's hierarchy of needs", def: "A model in which motives ascend from physiological needs through safety, belonging, esteem, to self-actualization." },
  { term: "Self-actualization", def: "Maslow's concept of realizing one's full personal potential." },
  { term: "Need to belong", def: "Baumeister & Leary's theory that connection to others is a fundamental human need with real physical consequences when unmet." },
  { term: "Ghrelin", def: "A stomach-released hormone that signals hunger." },
  { term: "Leptin", def: "A hormone released by fat cells that signals long-term energy stores to the brain." },
  { term: "Set point theory", def: "Theory that each person has a biologically defended body weight that resists short-term change." },
  { term: "Achievement motivation", def: "McClelland's drive to master tasks and meet high standards; predicts persistence and success." },
  { term: "Intrinsic motivation", def: "Doing something for its inherent satisfaction, not for external reward." },
  { term: "Extrinsic motivation", def: "Doing something for external reward or to avoid punishment." },
  { term: "Overjustification effect", def: "When external rewards undermine pre-existing intrinsic motivation." },
  { term: "Self-determination theory (Deci & Ryan)", def: "Theory that well-being requires autonomy, competence, and relatedness." },
  { term: "Emotion", def: "A complex response pattern with physiological, expressive, and subjective components." },
  { term: "James-Lange theory", def: "Theory that emotions result from the interpretation of bodily reactions — 'I'm afraid because my heart is racing.'" },
  { term: "Cannon-Bard theory", def: "Theory that physiological arousal and emotional experience occur simultaneously, both triggered by the brain." },
  { term: "Schachter-Singer two-factor theory", def: "Theory that emotion = physiological arousal + cognitive label for that arousal." },
  { term: "Appraisal theory (emotion)", def: "Lazarus's view that emotions result from our cognitive interpretation of a situation." },
  { term: "Facial feedback hypothesis", def: "The idea that facial expressions themselves can influence emotional experience." },
  { term: "Display rules", def: "Culture-specific norms dictating when and how emotions should be shown." },
  { term: "Emotional contagion", def: "The automatic tendency to mimic and catch others' emotions." },
  { term: "Broaden-and-build theory", def: "Fredrickson's theory that positive emotions broaden attention and build long-term psychological resources." },
  { term: "Emotional regulation", def: "The processes by which people influence which emotions they have, when, and how strongly they are expressed." },
  { term: "Cognitive reappraisal", def: "An emotion-regulation strategy of reinterpreting a situation's meaning; well-supported for mental health." },
  { term: "Expression suppression", def: "An emotion-regulation strategy of hiding felt emotion; generally less effective and linked to poorer outcomes." },

  // ═══ Chapter 13: Gender and Sexuality ═══
  { term: "Sex (biological)", def: "Biological characteristics — chromosomes, hormones, gonads, anatomy." },
  { term: "Gender", def: "The psychosocial dimensions of being man, woman, both, neither, or other; includes identity and roles." },
  { term: "Gender identity", def: "A person's internal sense of their own gender." },
  { term: "Gender role", def: "Culturally defined behaviors, attitudes, and traits expected of each gender." },
  { term: "Cisgender", def: "Having a gender identity matching one's assigned sex at birth." },
  { term: "Transgender", def: "Having a gender identity different from one's assigned sex at birth." },
  { term: "Intersex", def: "Biological variation in which sex characteristics don't fit typical male/female categories." },
  { term: "Androgyny (Bem)", def: "Psychological flexibility in expressing traits traditionally labeled masculine or feminine." },
  { term: "Gender similarities hypothesis (Hyde)", def: "Finding that on most psychological variables, sex differences are small or near-zero." },
  { term: "Sexual orientation", def: "The pattern of one's romantic and sexual attractions." },
  { term: "Fraternal birth order effect", def: "Each older brother a male has slightly increases his probability of homosexuality." },
  { term: "Sexual response cycle", def: "Masters & Johnson's model: excitement, plateau, orgasm, resolution." },
  { term: "Refractory period", def: "A post-orgasm interval during which further orgasm is physiologically not possible (typically longer for men)." },
  { term: "Passionate love", def: "Intense, aroused, often short-lived romantic love." },
  { term: "Companionate love", def: "Deep affection, trust, and commitment that develop over time." },
  { term: "Triangular theory of love (Sternberg)", def: "Love has three components — intimacy, passion, commitment — that combine into different types of love." },
  { term: "Sexual dysfunction", def: "Persistent problems with sexual response that cause distress." },
  { term: "Paraphilia", def: "Intense, persistent sexual interest in atypical objects, activities, or situations." },
  { term: "Gender dysphoria", def: "Distress arising from a mismatch between assigned sex and gender identity." },
  { term: "Consent (sexual)", def: "Voluntary, informed, ongoing agreement between capable partners; can be withdrawn at any time." },

  // ═══ Chapter 14: Personality ═══
  { term: "Personality", def: "The relatively stable pattern of thoughts, feelings, and behaviors that distinguish one person from another." },
  { term: "Trait", def: "A relatively stable disposition to behave in a particular way across situations." },
  { term: "Big Five (OCEAN)", def: "The well-replicated five-factor model of personality: Openness, Conscientiousness, Extraversion, Agreeableness, Neuroticism." },
  { term: "Openness to experience", def: "The Big Five trait of imagination, curiosity, and aesthetic sensitivity vs. preference for the familiar." },
  { term: "Conscientiousness", def: "The Big Five trait of self-discipline, organization, and reliability vs. spontaneity and carelessness." },
  { term: "Extraversion", def: "The Big Five trait of sociability, assertiveness, and energy from social contact vs. introversion." },
  { term: "Agreeableness", def: "The Big Five trait of warmth, cooperation, and trust vs. competitiveness and skepticism." },
  { term: "Neuroticism", def: "The Big Five trait of emotional volatility and tendency toward anxiety vs. emotional stability." },
  { term: "Dark Triad", def: "A trio of antagonistic traits: narcissism, Machiavellianism, psychopathy — linked to harmful interpersonal behavior." },
  { term: "Id", def: "Freud's primitive, unconscious part of personality operating on the pleasure principle." },
  { term: "Ego", def: "Freud's part of personality that mediates between id, superego, and reality, using the reality principle." },
  { term: "Superego", def: "Freud's internalized moral component of personality — conscience and ideals." },
  { term: "Defense mechanism", def: "Unconscious ego strategies (repression, denial, projection, etc.) that reduce anxiety from inner conflict." },
  { term: "Psychosexual stages", def: "Freud's stages (oral, anal, phallic, latency, genital) through which personality develops." },
  { term: "Self-concept", def: "A person's view of themselves — their attributes, abilities, and identity." },
  { term: "Unconditional positive regard", def: "Rogers's concept of valuing a person regardless of their behavior; supports healthy self-concept." },
  { term: "Reciprocal determinism", def: "Bandura's idea that person, behavior, and environment continuously influence each other." },
  { term: "Self-efficacy", def: "Bandura's concept of one's belief in their ability to succeed at specific tasks." },
  { term: "Locus of control", def: "Rotter's concept of whether one sees outcomes as driven by internal actions or external forces." },
  { term: "Personality disorder", def: "An enduring, pervasive pattern of inner experience and behavior that deviates markedly from cultural expectations and causes distress or impairment." },
  { term: "MMPI-2", def: "The Minnesota Multiphasic Personality Inventory — the most widely used self-report clinical personality test." },
  { term: "NEO-PI-R", def: "A widely used self-report inventory measuring the Big Five personality traits." },
  { term: "Rorschach inkblot test", def: "A projective test in which ambiguous inkblots are interpreted; low reliability and validity by modern standards." },
  { term: "Thematic Apperception Test (TAT)", def: "A projective test in which people tell stories about ambiguous pictures." },

  // ═══ Chapter 15: Health, Stress, and Coping ═══
  { term: "Stress", def: "The physical, emotional, and cognitive response to events perceived as threatening or demanding." },
  { term: "Stressor", def: "Any event or condition that triggers a stress response." },
  { term: "Primary appraisal", def: "Lazarus's first cognitive step: deciding whether an event is threatening." },
  { term: "Secondary appraisal", def: "Lazarus's second cognitive step: deciding whether you have the resources to cope." },
  { term: "HPA axis", def: "Hypothalamic-Pituitary-Adrenal axis — a slow, cortisol-driven stress pathway critical in chronic stress." },
  { term: "Cortisol", def: "A stress hormone released from the adrenal cortex that mobilizes energy and modulates many body systems; chronic elevation is damaging." },
  { term: "General Adaptation Syndrome (GAS)", def: "Selye's three-stage model of the body's response to prolonged stress: alarm, resistance, exhaustion." },
  { term: "Health psychology", def: "The subfield that studies how psychological factors affect physical health and illness." },
  { term: "Type A behavior pattern", def: "Original Friedman & Rosenman pattern of impatience, hostility, and competitiveness linked to heart disease; later refined to implicate hostility specifically." },
  { term: "Psychoneuroimmunology (PNI)", def: "The field studying interactions between psychological processes, the nervous system, and immune function." },
  { term: "Problem-focused coping", def: "Directly addressing the source of stress; works best when the stressor is controllable." },
  { term: "Emotion-focused coping", def: "Managing the feelings caused by stress; appropriate when the stressor itself can't be changed." },
  { term: "Social support", def: "Emotional, informational, or tangible help from others — a major protective factor against stress." },
  { term: "Resilience", def: "The capacity to adapt and recover from adversity; partly trait-like, substantially buildable." },
  { term: "Placebo effect", def: "Changes in behavior or physiology caused by the belief that one has received a treatment." },
  { term: "Nocebo effect", def: "Negative outcomes produced by expectations of harm — the mirror image of the placebo effect." },

  // ═══ Chapter 16: Psychological Disorders ═══
  { term: "Four D's (of disorder)", def: "Distress, Dysfunction, Deviance, Danger — clinical criteria used to identify mental disorders." },
  { term: "DSM-5", def: "Diagnostic and Statistical Manual of Mental Disorders, 5th edition — the primary diagnostic classification system in North America." },
  { term: "Comorbidity", def: "The co-occurrence of two or more disorders in the same person — the rule rather than the exception." },
  { term: "Generalized anxiety disorder (GAD)", def: "Persistent, excessive worry across multiple domains with physical tension symptoms." },
  { term: "Panic disorder", def: "Recurrent, unexpected panic attacks and persistent concern about having more." },
  { term: "Specific phobia", def: "Intense, persistent fear of a specific object or situation out of proportion to actual danger." },
  { term: "Social anxiety disorder", def: "Marked fear of social or performance situations involving scrutiny by others." },
  { term: "Agoraphobia", def: "Fear of situations where escape would be difficult; can result in being housebound." },
  { term: "Obsessive-compulsive disorder (OCD)", def: "A disorder marked by intrusive obsessions and compulsive behaviors performed to reduce the anxiety." },
  { term: "Post-traumatic stress disorder (PTSD)", def: "A trauma- and stressor-related disorder with intrusive re-experiencing, avoidance, negative mood, and hyperarousal." },
  { term: "Major depressive disorder (MDD)", def: "Persistent depressed mood or loss of interest lasting at least two weeks, plus associated cognitive and physical symptoms." },
  { term: "Persistent depressive disorder (dysthymia)", def: "Chronic low-level depression lasting two or more years." },
  { term: "Bipolar disorder", def: "A mood disorder involving episodes of depression and mania (I) or hypomania (II)." },
  { term: "Mania", def: "An elevated, irritable, or expansive mood state with decreased need for sleep, racing thoughts, and impulsive behavior." },
  { term: "Cognitive triad (Beck)", def: "Negative views of self, world, and future characterizing depression." },
  { term: "Schizophrenia", def: "A chronic psychiatric disorder involving positive symptoms (hallucinations, delusions), negative symptoms, and cognitive symptoms." },
  { term: "Positive symptoms", def: "Additions to normal experience — hallucinations, delusions, disorganized thought." },
  { term: "Negative symptoms", def: "Reductions in normal function — flat affect, social withdrawal, reduced motivation." },
  { term: "Dopamine hypothesis of schizophrenia", def: "The theory that positive symptoms arise from excess dopamine activity in mesolimbic pathways." },
  { term: "Dissociative identity disorder (DID)", def: "A rare and controversial disorder involving two or more distinct personality states." },
  { term: "Biopsychosocial model", def: "The view that psychological disorders arise from interacting biological, psychological, and social factors." },
  { term: "Diathesis-stress model", def: "A framework in which genetic or constitutional vulnerabilities only produce disorder when combined with sufficient stress." },
  { term: "ADHD", def: "Attention-deficit/hyperactivity disorder — persistent inattention and/or hyperactivity-impulsivity interfering with function." },
  { term: "Autism spectrum disorder (ASD)", def: "A neurodevelopmental condition involving differences in social communication and restricted repetitive behaviors, with wide variation across individuals." },

  // ═══ Chapter 17: Therapies ═══
  { term: "Psychotherapy", def: "Treatment of psychological problems through structured conversation between client and therapist." },
  { term: "Biomedical therapy", def: "Treatment of psychological disorders with medication or somatic interventions (ECT, TMS, etc.)." },
  { term: "Psychodynamic therapy", def: "A treatment descended from psychoanalysis that explores unconscious conflicts and relational patterns." },
  { term: "Free association", def: "A psychoanalytic technique in which the patient verbalizes whatever comes to mind without censorship." },
  { term: "Transference", def: "A psychoanalytic concept in which the client unconsciously projects feelings from past relationships onto the therapist." },
  { term: "Client-centered therapy", def: "Carl Rogers's humanistic therapy emphasizing empathy, unconditional positive regard, and congruence." },
  { term: "Systematic desensitization", def: "Wolpe's behavior therapy pairing relaxation with a graded hierarchy of feared stimuli." },
  { term: "Exposure therapy", def: "Repeated, controlled contact with feared stimuli to extinguish the fear response; gold standard for phobias and PTSD." },
  { term: "Exposure and response prevention (ERP)", def: "A specialized exposure-based treatment for OCD in which compulsions are prevented." },
  { term: "Behavioral activation", def: "A depression treatment that systematically increases engagement with pleasurable and meaningful activities." },
  { term: "Cognitive therapy", def: "Aaron Beck's approach of identifying and challenging distorted thought patterns." },
  { term: "REBT", def: "Albert Ellis's Rational Emotive Behavior Therapy; A-B-C model: activating event, belief, consequence." },
  { term: "Cognitive-behavioral therapy (CBT)", def: "The integrated cognitive-plus-behavioral approach with the strongest evidence base across many conditions." },
  { term: "Dialectical Behavior Therapy (DBT)", def: "Marsha Linehan's treatment combining CBT, mindfulness, distress tolerance, emotion regulation, and interpersonal effectiveness." },
  { term: "Acceptance and Commitment Therapy (ACT)", def: "A third-wave therapy emphasizing psychological flexibility: accepting thoughts and committing to value-driven action." },
  { term: "SSRI", def: "Selective Serotonin Reuptake Inhibitors — the most widely used antidepressants (Prozac, Zoloft, etc.)." },
  { term: "Antipsychotic", def: "Medication that reduces psychotic symptoms primarily by blocking dopamine receptors." },
  { term: "Lithium", def: "A long-established mood stabilizer, first-line for bipolar disorder." },
  { term: "Electroconvulsive therapy (ECT)", def: "A treatment inducing a brief seizure under anesthesia; highly effective for severe, treatment-resistant depression." },
  { term: "Transcranial magnetic stimulation (TMS)", def: "Non-invasive magnetic stimulation of targeted brain areas; approved for treatment-resistant depression." },
  { term: "Therapeutic alliance", def: "The trust and collaborative relationship between client and therapist; among the strongest predictors of therapy success." },
  { term: "Common factors", def: "Therapeutic ingredients shared across approaches (alliance, hope, coherent explanation, active participation) that account for much of therapy's effect." },

  // ═══ Chapter 18: Social Behavior ═══
  { term: "Social psychology", def: "The scientific study of how people's thoughts, feelings, and behaviors are influenced by the presence of others." },
  { term: "Conformity", def: "Changing one's behavior or beliefs to match those of a group (Asch)." },
  { term: "Normative social influence", def: "Conformity motivated by desire to be liked or accepted." },
  { term: "Informational social influence", def: "Conformity based on using others' judgments as information, especially in ambiguous situations." },
  { term: "Obedience (Milgram)", def: "Complying with direct orders from an authority figure, even when those orders violate personal values." },
  { term: "Social facilitation", def: "Improved performance on simple/well-practiced tasks in the presence of others." },
  { term: "Social loafing", def: "Reduced individual effort when working in a group where contributions aren't individually identified." },
  { term: "Deindividuation", def: "Loss of self-awareness and individual identity in group settings, especially when anonymous." },
  { term: "Bystander effect", def: "The finding that people are less likely to help in an emergency when more witnesses are present." },
  { term: "Diffusion of responsibility", def: "The tendency for individuals to feel less personal obligation to act when others are present." },
  { term: "Pluralistic ignorance", def: "A situation in which everyone misinterprets the collective inaction as evidence that no action is needed." },
  { term: "Group polarization", def: "The tendency for group discussion to make pre-existing attitudes more extreme." },
  { term: "Groupthink", def: "A group decision-making pathology in which the desire for harmony overrides realistic appraisal." },
  { term: "Attribution", def: "The process of assigning causes to one's own or others' behavior." },
  { term: "Fundamental attribution error (FAE)", def: "The tendency to over-weight dispositional causes and under-weight situational ones when explaining others' behavior." },
  { term: "Actor-observer bias", def: "Attributing one's own behavior to situational causes but others' behavior to dispositional ones." },
  { term: "Self-serving bias", def: "Attributing one's own successes to internal factors and failures to external ones." },
  { term: "Just-world hypothesis", def: "The belief that the world is fundamentally fair, which can lead to blaming victims." },
  { term: "Cognitive dissonance", def: "The uncomfortable tension produced by holding two inconsistent thoughts, motivating attitude change (Festinger)." },
  { term: "Elaboration Likelihood Model (ELM)", def: "Petty & Cacioppo's dual-route model of persuasion: central (argument quality) and peripheral (cues)." },
  { term: "Cialdini's principles of influence", def: "Six principles of persuasion — reciprocity, commitment/consistency, social proof, liking, authority, scarcity." },
  { term: "Frustration-aggression hypothesis", def: "The idea that frustration increases aggressive urges; later refined to account for many modulators." },
  { term: "Altruism", def: "Behavior intended to benefit another at potential cost to oneself." },
  { term: "Empathy-altruism hypothesis (Batson)", def: "The theory that genuine empathy motivates helping independent of self-interest." },

  // ═══ Chapter 19: Attitudes, Culture, and Human Relations ═══
  { term: "Attitude", def: "An evaluative stance toward a person, object, or idea — with affective, behavioral, and cognitive components." },
  { term: "Mere exposure effect", def: "The tendency to develop a preference for stimuli simply through repeated exposure (Zajonc)." },
  { term: "Stereotype", def: "A cognitive generalization about a social group." },
  { term: "Prejudice", def: "A negative emotional evaluation of a group; the affective component." },
  { term: "Discrimination", def: "Differential behavior toward people based on group membership; the behavioral component." },
  { term: "In-group bias", def: "The automatic tendency to favor groups to which one belongs." },
  { term: "Social identity theory (Tajfel & Turner)", def: "The view that self-esteem draws from group membership, motivating favorable in-group / unfavorable out-group comparisons." },
  { term: "Realistic conflict theory", def: "Sherif's theory that intergroup hostility arises from competition over scarce resources." },
  { term: "Robbers Cave experiment", def: "Sherif's 1954 summer-camp study that created intergroup hostility through competition and reduced it through shared goals." },
  { term: "Implicit bias", def: "Automatic associations about social groups that can operate without conscious awareness, often measured with the IAT." },
  { term: "Contact hypothesis (Allport)", def: "The proposition that intergroup prejudice can be reduced by contact under conditions of equal status, common goals, cooperation, and institutional support." },
  { term: "Interpersonal attraction", def: "The factors that lead people to like one another — proximity, similarity, reciprocal liking, physical attractiveness." },
  { term: "Individualism vs. collectivism", def: "A major cultural dimension distinguishing prioritization of individual achievement vs. group harmony." },
  { term: "Power distance", def: "A cultural dimension capturing how much hierarchy a culture accepts as natural." },
  { term: "Tight vs. loose cultures (Gelfand)", def: "Cultures differ in how strictly social norms are enforced and how much deviance is tolerated." },
  { term: "Independent vs. interdependent self-construal", def: "The psychological self-view characteristic of individualist vs. collectivist cultures." },
  { term: "Acculturation", def: "The psychological and behavioral changes that occur when people move between cultures." },
  { term: "Multiculturalism", def: "Approach that acknowledges and values cultural differences within diverse societies, contrasted with color-blind approaches." },

  // ═══ Chapter 20: Applied Psychology ═══
  { term: "Applied psychology", def: "The use of psychological findings to solve real-world problems across domains (work, education, law, health, design)." },
  { term: "Industrial-organizational (I-O) psychology", def: "The subfield applying psychology to workplace selection, training, leadership, motivation, and design." },
  { term: "Theory X / Theory Y (McGregor)", def: "Contrasting assumptions about workers: X = lazy, needs control; Y = self-directed, seeks meaning." },
  { term: "Job Characteristics Model", def: "Hackman & Oldham's framework of five features driving motivation and satisfaction: skill variety, task identity, significance, autonomy, feedback." },
  { term: "Environmental psychology", def: "The study of how physical environments affect behavior and how to design them to support human flourishing." },
  { term: "Attention restoration theory", def: "Kaplan's theory that exposure to nature allows recovery from focused-attention fatigue." },
  { term: "Educational psychology", def: "The subfield applying learning and developmental research to teaching and schooling." },
  { term: "Pygmalion effect", def: "Rosenthal & Jacobson's finding that teacher expectations can become self-fulfilling for student performance." },
  { term: "Sports psychology", def: "The application of psychological principles to athletic performance, motivation, and well-being." },
  { term: "Forensic psychology", def: "The application of psychology to the legal system — eyewitnesses, juries, confessions, risk assessment." },
  { term: "Consumer psychology", def: "The study of how psychological principles affect purchasing decisions and marketing." },
  { term: "Human factors psychology (ergonomics)", def: "The design of tools, systems, and environments to fit human capabilities and limitations." },
  { term: "Choice architecture (Thaler & Sunstein)", def: "The deliberate design of how options are presented — shaping decisions without restricting choice." },
  { term: "Community psychology", def: "A subfield focused on the interaction of individuals and social systems, aimed at changing systems to improve well-being." },

  // ═══ Supplemental terms (broader common-term coverage) ═══
  { term: "Abnormal psychology", def: "The branch of psychology that studies psychological disorders, their causes, and treatment." },
  { term: "Affective forecasting", def: "Predicting one's own future emotional reactions; people systematically overestimate the intensity and duration of both positive and negative feelings (Wilson & Gilbert)." },
  { term: "Aggression", def: "Behavior intended to harm another person physically or psychologically." },
  { term: "Behavior modification", def: "The systematic application of operant-conditioning principles to change specific behaviors." },
  { term: "Binge eating disorder", def: "An eating disorder marked by recurrent episodes of consuming large amounts of food with loss of control, without the compensatory behaviors seen in bulimia." },
  { term: "Defense mechanisms", def: "Unconscious ego strategies (repression, denial, projection, displacement, sublimation, etc.) that reduce anxiety from inner conflict; plural form of 'defense mechanism.'" },
  { term: "Delay of gratification", def: "The ability to resist a smaller immediate reward in favor of a larger later one; famously studied in Mischel's marshmallow experiments." },
  { term: "Ego depletion", def: "The hypothesis that self-control draws on a limited resource that depletes with use; large-scale replications have produced mixed results, and the strong version is contested." },
  { term: "Empathy", def: "The capacity to understand and share another person's emotional experience; central to social bonding and prosocial behavior." },
  { term: "Existential crisis", def: "A period of intense questioning about the meaning, purpose, or value of one's existence, often triggered by major life transitions or losses." },
  { term: "Flow", def: "Csikszentmihalyi's term for a state of complete absorption in an activity, with clear goals, immediate feedback, and a challenge matched to one's skill level." },
  { term: "Gestalt therapy", def: "A humanistic therapy (Fritz Perls) emphasizing present-moment awareness, personal responsibility, and integration of disowned aspects of the self." },
  { term: "Habituation", def: "A simple form of learning in which a repeatedly presented stimulus produces a progressively reduced response." },
  { term: "Learned helplessness", def: "Seligman's finding that organisms exposed to inescapable aversive events later fail to escape when escape becomes possible; an influential model of depression." },
  { term: "Neuroplasticity", def: "The brain's capacity to change its structure and function in response to experience, learning, and injury." },
  { term: "Projection (defense mechanism)", def: "Attributing one's own unacceptable impulses, feelings, or thoughts to other people." },
  { term: "Psychosomatic illness", def: "An older term for physical illness caused or substantially worsened by psychological factors; modern usage prefers 'psychophysiological disorder.'" },
  { term: "Regression (defense mechanism)", def: "Reverting to behaviors typical of an earlier developmental stage when under stress." },
  { term: "Somatic symptom disorder", def: "A DSM-5 disorder involving distressing physical symptoms accompanied by disproportionate thoughts, feelings, or behaviors about them." },
  { term: "Stigma (mental illness)", def: "Negative social labeling, stereotyping, and discrimination directed at people with mental illness; delays help-seeking and worsens outcomes." },
  { term: "Sublimation", def: "A defense mechanism in which unacceptable impulses are channeled into socially valued activities (e.g., aggression into competitive sports, anxiety into productive work)." },
  { term: "Xenophobia", def: "Fear, distrust, or hostility toward people perceived as foreign or different; an extreme manifestation of out-group bias." },

  // ═══ Unit 9 — Advanced Concepts ═══
  // Psychoanalytic / Jungian deep concepts
  { term: "Libido", def: "Freud's term for life energy or sexual instinct; later broadened to encompass all life-affirming drives (Eros)." },
  { term: "Death drive (Thanatos)", def: "Freud's later, controversial proposal that humans have an inward-pushing aggressive and self-destructive drive alongside life-affirming Eros." },
  { term: "Pleasure principle", def: "Freud's rule for the id: seek immediate gratification and avoid pain." },
  { term: "Reality principle", def: "Freud's rule for the ego: delay gratification when reality requires it; pick optimal action under constraint." },
  { term: "Displacement", def: "A defense mechanism redirecting an impulse from a threatening target to a safer one (yelling at the dog after a bad day)." },
  { term: "Reaction formation", def: "A defense mechanism in which one expresses the opposite of an unacceptable feeling." },
  { term: "Rationalization", def: "A defense mechanism of generating acceptable reasons for behavior driven by unacceptable motives." },
  { term: "Intellectualization", def: "A defense mechanism of focusing on facts and logic to avoid emotional experience." },
  { term: "Freudian slip (parapraxis)", def: "An error in speech, memory, or action interpreted as revealing an unconscious thought; modern cognitive psychology often explains them as ordinary speech-production errors." },
  { term: "Dream analysis", def: "A psychoanalytic technique interpreting manifest content as a disguised expression of latent unconscious meaning; empirical support is weak by modern standards." },
  { term: "Manifest content", def: "Freud's term for what a dreamer actually remembers of a dream — the surface story." },
  { term: "Latent content", def: "Freud's term for the supposed hidden symbolic meaning beneath the manifest dream." },
  { term: "Dreamwork", def: "Freud's term for the unconscious processes (condensation, displacement, symbolization) that transform latent into manifest dream content." },
  { term: "Oedipus complex", def: "Freud's claim that boys ages 3–6 develop unconscious sexual desire for their mother and rivalrous hostility toward their father; not supported as a universal stage in modern research." },
  { term: "Electra complex", def: "Jung's female parallel to the Oedipus complex; not supported empirically as a universal phenomenon." },
  { term: "Countertransference", def: "The therapist's own emotional reactions to a client, sometimes triggered by the client's transference; can be a clinical asset or hindrance." },
  { term: "Object relations", def: "A psychodynamic theory (Klein, Winnicott) emphasizing internalized mental representations of important others, which shape later relationships." },
  { term: "Personal unconscious (Jung)", def: "Jung's term for an individual's repressed and forgotten content — comparable to Freud's unconscious." },
  { term: "Collective unconscious", def: "Jung's controversial proposal of a deeper, inherited psychic layer shared by all humans, populated by archetypes." },
  { term: "Archetypes", def: "Jung's universal patterns appearing across cultures, mythologies, and dreams (the Self, Shadow, Anima, Animus, Hero, Wise Old Man, etc.)." },
  { term: "Anima / Animus", def: "Jungian archetypes representing the unconscious feminine aspect in men (anima) and unconscious masculine aspect in women (animus)." },
  { term: "Shadow (Jung)", def: "The Jungian archetype of the disowned, often 'darker' parts of personality that we repress or hide." },
  { term: "Persona (Jung)", def: "The Jungian archetype representing the social mask one presents to the world." },
  { term: "Synchronicity", def: "Jung's term for meaningful coincidences linked by meaning rather than physical causation; not supported empirically." },
  { term: "Individuation (Jung)", def: "Jung's term for the lifelong process of integrating conscious and unconscious aspects to become a whole, authentic self." },
  { term: "Introversion", def: "A personality orientation toward inner experience, low arousal preference, and gaining energy from solitude (term coined by Jung)." },

  // Behaviorism deep concepts
  { term: "Counterconditioning", def: "A behavior-therapy technique that replaces an unwanted conditioned response with a new, incompatible response (e.g., relaxation paired with feared stimuli)." },
  { term: "Aversion therapy", def: "Pairing an unwanted behavior with an unpleasant stimulus to reduce the behavior; ethically restricted, with a troubled history." },
  { term: "Continuous reinforcement", def: "A schedule in which every correct response is reinforced; produces fast learning but rapid extinction." },
  { term: "Partial (intermittent) reinforcement", def: "A schedule in which only some responses are reinforced; produces slower learning but stronger resistance to extinction." },
  { term: "Partial reinforcement extinction effect", def: "The finding that behavior learned under partial reinforcement extinguishes more slowly than behavior learned under continuous reinforcement." },
  { term: "Behavior chain", def: "A sequence of operant behaviors linked together, where each step's completion serves as a discriminative stimulus and reinforcer for the next." },
  { term: "Forward chaining", def: "Teaching a behavior chain step by step from the first to the last." },
  { term: "Backward chaining", def: "Teaching a behavior chain by starting with the final step and adding earlier steps progressively." },
  { term: "Motivating operations (MOs)", def: "Events that change the value of a reinforcer or punisher (Jack Michael); includes establishing operations and abolishing operations." },
  { term: "Premack principle", def: "Premack's finding that a high-probability behavior can serve as a reinforcer for a lower-probability behavior ('eat your vegetables, then dessert')." },
  { term: "Token economy", def: "A structured behavior-modification system in which target behaviors earn tokens exchangeable for desired items or privileges." },
  { term: "Behavior chain (terminal)", def: "The complete operant sequence, with the final reinforcer at the end of the chain." },
  { term: "Functional behavior assessment (FBA)", def: "A structured ABA analysis of the antecedents, behavior, and consequences (ABC) maintaining a problem behavior." },
  { term: "Applied Behavior Analysis (ABA)", def: "A field that applies behavioral principles to socially significant problems, especially in autism, education, and developmental disabilities." },

  // Cognitive deep concepts
  { term: "Schema", def: "A mental framework that organizes related information and expectations, shaping perception, attention, and memory." },
  { term: "Script", def: "A type of schema for a sequence of events (e.g., 'restaurant script,' 'first-date script')." },
  { term: "Selective attention", def: "Focusing cognitive resources on one stream of input while filtering out others; the cocktail-party effect is the classic illustration." },
  { term: "Divided attention", def: "Splitting attention across multiple inputs or tasks; humans are poor at this for tasks requiring judgment." },
  { term: "Attentional resources", def: "The brain's limited processing capacity drawn down by effortful tasks (Kahneman)." },
  { term: "Sustained attention (vigilance)", def: "The ability to maintain focus over extended time; performance reliably degrades after ~20-30 minutes." },
  { term: "Cognitive load theory (Sweller)", def: "Theory distinguishing intrinsic, extraneous, and germane cognitive loads, used to design effective instruction." },
  { term: "Intrinsic cognitive load", def: "Mental effort required by the inherent difficulty of the material itself." },
  { term: "Extraneous cognitive load", def: "Wasted mental effort caused by poor presentation or distraction." },
  { term: "Germane cognitive load", def: "Productive mental effort that builds schemas and supports learning." },
  { term: "Dual-coding theory (Paivio)", def: "Theory that information is processed in two systems — verbal and imagery — and is remembered better when encoded in both." },
  { term: "Multimedia principle", def: "Mayer's finding that people learn better from words and pictures than from words alone." },
  { term: "Prospective memory", def: "Remembering to perform actions at a future time (e.g., 'pick up milk on the way home')." },
  { term: "Metacognition", def: "Thinking about one's own thinking — awareness of and control over cognitive processes; predicts effective learning." },
  { term: "Self-explanation effect", def: "The robust finding that explaining material to oneself while studying produces deeper learning than passive review." },
  { term: "Higher-order thinking", def: "Cognitive skills beyond rote recall — applying, analyzing, evaluating, creating; corresponds to upper levels of Bloom's taxonomy." },
  { term: "Bloom's taxonomy", def: "Bloom's hierarchy of cognitive skills (revised): Remember, Understand, Apply, Analyze, Evaluate, Create — used widely in education." },
  { term: "Cognitive tool", def: "Anything (mental representation, technique, or external aid) that augments thinking — from notation to spreadsheets to language itself." },

  // Social cognition / Vygotsky
  { term: "Social cognition", def: "The study of how people process information about others and themselves in social contexts." },
  { term: "Automatic vs. controlled social cognition", def: "The distinction between fast, unconscious social judgments and slower, deliberate ones." },
  { term: "Stereotyping", def: "Applying generalized group-level expectations to individuals, often automatically; can produce real harm despite some statistical accuracy." },
  { term: "Out-group homogeneity effect", def: "The tendency to see members of out-groups as more similar to each other than they really are, while seeing one's in-group as full of distinct individuals." },
  { term: "Social comparison theory", def: "Festinger's theory that humans evaluate themselves through comparison with others — upward comparisons can motivate or deflate." },
  { term: "Social exchange theory", def: "A framework treating relationships as ongoing implicit exchanges of costs and benefits (Homans, Blau, Thibaut & Kelley)." },
  { term: "Reciprocity norm", def: "The near-universal cultural rule that one should return favors and treat others as they treat you; one of Cialdini's six influence principles." },
  { term: "Private speech (Vygotsky)", def: "Children's audible self-directed talk during difficult tasks; a self-regulation tool that becomes inner speech as it's internalized." },
  { term: "Inner speech", def: "Internalized language used for self-regulation and thinking; develops from earlier private speech." },
  { term: "Guided participation (Rogoff)", def: "A form of cultural learning in which children participate in adult activities at developmentally appropriate levels, often without explicit instruction." },
  { term: "Cognitive apprenticeships", def: "An instructional approach (Collins, Brown, Newman) applying traditional craft-apprenticeship principles to cognitive skills: modeling, coaching, scaffolding, articulation, reflection, exploration." },
  { term: "Distributed cognition", def: "The view that thinking is fundamentally distributed across the brain, body, tools, and culture, not contained within an individual head." },

  // Humanistic deep concepts
  { term: "Actualizing tendency (Rogers)", def: "Rogers's proposed inherent biological drive in all life to maintain and develop the organism — in humans, the impulse toward fulfilling one's potential." },
  { term: "Conditions of worth", def: "Rogers's term for implicit messages that one is only worthy of love when meeting specific external standards; produce incongruence and distress." },
  { term: "Congruence (Rogers)", def: "The match between authentic experience and self-concept (in clients) and authentic presence vs. performed role (in therapists)." },
  { term: "Incongruence (Rogers)", def: "A gap between authentic experience and self-concept; identified by Rogers as the root of most psychological distress." },
  { term: "Person-centered therapy", def: "Carl Rogers's humanistic therapy emphasizing unconditional positive regard, empathy, and congruence; client takes the lead." },
  { term: "Deficiency needs (D-needs)", def: "Maslow's lower needs (physiological, safety, belonging, esteem) that are felt as deficits and reduce when satisfied." },
  { term: "Growth needs (B-needs)", def: "Maslow's higher needs (cognitive, aesthetic, self-actualization, transcendence) that increase rather than decrease as engaged with." },
  { term: "Peak experience", def: "Maslow's term for an intense moment of joy, awe, or unity that produces lasting positive effects; overlaps with flow and self-transcendent experience." },
  { term: "Mastery", def: "The deep skill achieved through long deliberate practice; one of Pink's three motivators (autonomy, mastery, purpose)." },
  { term: "Deliberate practice (Ericsson)", def: "Structured pursuit of skills just beyond one's current ability, with feedback; distinct from rote repetition." },
  { term: "Autonomy (psychological)", def: "The feeling that one's actions are self-chosen and reflect one's own values; one of self-determination theory's three basic needs." },
  { term: "Self-transcendent experience", def: "Modern psychology's term for moments of expanded awareness, unity, and reduced self-focus; overlaps with peak experiences and flow states." },
];
